{
  "name": "示例虚拟仪器",
  "name_en": "Example Virtual Instrument",
  "manufacturer": "",
  "description": "一个用于实验控制软件测试、演示和流程验证的示例性虚拟仪器，不对应明确的实际硬件型号。它可用于模拟参数更新、数值读取、连接状态检查、复位和控制输出等常见实验仪器交互。",
  "description_en": "A sample virtual instrument used for testing, demonstration, and workflow validation in laboratory control software. It does not correspond to a specific physical hardware model, but can simulate common instrument interactions such as parameter updates, value readout, connection checks, reset, and controller output handling.",
  "tag_hints": [
    "virtual instrument",
    "dummy device",
    "instrument simulation",
    "lab software testing",
    "control workflow demo"
  ],
  "actions": [
    {
      "action_name": "auto-read_probes",
      "description": "读取指定探针或测量项的当前值",
      "description_en": "Read the current value of a specified probe or measurement item."
    },
    {
      "action_name": "auto-update",
      "description": "更新仪器参数设置",
      "description_en": "Update instrument parameter settings."
    },
    {
      "action_name": "auto-is_connected",
      "description": "获取连接状态",
      "description_en": "Get connection status."
    },
    {
      "action_name": "auto-quit",
      "description": "退出或停止仪器会话",
      "description_en": "Quit or stop the instrument session."
    },
    {
      "action_name": "auto-reset",
      "description": "将仪器重置到初始状态",
      "description_en": "Reset the instrument to its initial state."
    },
    {
      "action_name": "auto-controler_output",
      "description": "获取控制器输出值",
      "description_en": "Get the controller output value."
    }
  ]
}

